export const spaces=[{name:'Автосервис',type:'01 / АВТОСЕРВИС',desc:'Выберите класс автомобиля, рассчитайте стоимость услуг и попробуйте демозапись.',x:120,y:260,w:150,d:100,h:65,active:true},{name:'Магазин',type:'02 / МАГАЗИН',desc:'Каталог предметов, фильтры, корзина и демонстрационное оформление заказа.',x:340,y:240,w:130,d:100,h:95},{name:'Творческая студия',type:'03 / СТУДИЯ',desc:'Галерея идей и авторских проектов с возможностью составить бриф.',x:120,y:65,w:115,d:95,h:85},{name:'Центр управления',type:'04 / УПРАВЛЕНИЕ',desc:'Посмотрите демозаписи и заказы и управляйте их статусами.',x:350,y:65,w:85,d:80,h:130}];
spaces.forEach(o=>o.active=true);
export const p=(x,y,z=0)=>[660+(x-y)*.93,205+(x+y)*.48-z];
const poly=(pts,fill,cls='')=>`<polygon class="${cls}" points="${pts.map(a=>p(...a).join(',')).join(' ')}" fill="${fill}"/>`;
export function box(x,y,w,d,h,base='#e9e9df'){return poly([[x,y,0],[x+w,y,0],[x+w,y,h],[x,y,h]],'#c3c9bc')+poly([[x+w,y,0],[x+w,y+d,0],[x+w,y+d,h],[x+w,y,h]],'#aab4a3')+poly([[x,y+d,0],[x+w,y+d,0],[x+w,y+d,h],[x,y+d,h]],base)+poly([[x,y,h],[x+w,y,h],[x+w,y+d,h],[x,y+d,h]],'#f9f8f0','roof');}
// Seeded cellular coast: cellular smoothing shapes the terrain mask; fixed seed keeps the map stable across visits.
function terrain(){const rows=32,cols=42,seed=721956;let state=seed>>>0;const random=()=>{state=(state*1664525+1013904223)>>>0;return state/4294967296};let grid=Array.from({length:rows},(_,y)=>Array.from({length:cols},(_,x)=>{const nx=(x-cols/2)/(cols*.47),ny=(y-rows/2)/(rows*.46),inside=nx*nx+ny*ny<1;return inside&&(random()>.17)?1:0}));for(let step=0;step<4;step++){const next=grid.map(row=>row.slice());for(let y=1;y<rows-1;y++)for(let x=1;x<cols-1;x++){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(dx||dy)n+=grid[y+dy][x+dx];next[y][x]=n>=5?1:n<=2?0:grid[y][x]}grid=next}let out='';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)if(grid[y][x]){const wx=57+x*10.4,wy=55+y*10.3;let edge=false;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(!grid[y+dy]?.[x+dx])edge=true;const color=edge?'#d7d1b9':((x*7+y*11)%9===0?'#b8c5a8':'#cbd3bb');out+=poly([[wx,wy,2],[wx+10.45,wy,2],[wx+10.45,wy+10.35,2],[wx,wy+10.35,2]],color)}return out}
export function scene(){let s='<ellipse cx="690" cy="595" rx="350" ry="75" fill="#74816b" opacity=".16" filter="url(#shadow)"/>';s+=box(0,0,550,440, -24,'#c9cdbd');s+=poly([[0,0,0],[550,0,0],[550,440,0],[0,440,0]],'#e1e4d4');s+=poly([[32,30,1],[520,30,1],[520,410,1],[32,410,1]],'#c2c9ba');s+=poly([[57,55,2],[495,55,2],[495,385,2],[57,385,2]],'#e5e7da');s+=`<g class="procedural-terrain" pointer-events="none" aria-hidden="true">${terrain()}</g>`;s+=poly([[70,195,3],[490,195,3],[490,220,3],[70,220,3]],'#c3cabb');s+=poly([[285,55,3],[310,55,3],[310,385,3],[285,385,3]],'#c3cabb');for(let i=0;i<16;i++){let x=65+i*27;s+=poly([[x,397,3],[x+12,397,3],[x+12,399,3],[x,399,3]],'#eef0e5');}const trees=[[75,80],[70,140],[270,85],[320,90],[470,90],[475,160],[75,300],[90,360],[330,350],[460,355],[480,290],[235,155]];for(const [x,y] of trees){const [a,b]=p(x,y);s+=`<ellipse cx="${a+10}" cy="${b+4}" rx="18" ry="8" fill="#bdc7b1"/><path d="M${a} ${b}v-24" stroke="#899078" stroke-width="4"/><ellipse cx="${a}" cy="${b-30}" rx="18" ry="24" fill="#9caa87"/><ellipse cx="${a-5}" cy="${b-35}" rx="12" ry="17" fill="#b0bd9c"/>`;}
for(const i of [2,3,0,1]){const o=spaces[i];s+=`<g class="building" tabindex="0" role="button" aria-label="${o.name}${o.active?' — открыть карточку':' — скоро'}" data-id="${i}">`+box(o.x,o.y,o.w,o.d,o.h);for(let k=0;k<3;k++)s+=poly([[o.x+12+k*o.w/3,o.y+o.d+0.1,12],[o.x+30+k*o.w/3,o.y+o.d+.1,12],[o.x+30+k*o.w/3,o.y+o.d+.1,o.h-14],[o.x+12+k*o.w/3,o.y+o.d+.1,o.h-14]],i===0?'#52645b':'#a0afa2');s+=box(o.x+12,o.y+12,o.w-24,12,o.h+9,'#d8ddcf');const [a,b]=p(o.x+o.w/2,o.y+o.d+30);s+=`<text class="maplabel" x="${a}" y="${b}" text-anchor="middle">0${i+1} / ${o.name.toUpperCase()}</text></g>`;}s+='<g id="car"><rect x="-12" y="-6" width="24" height="12" rx="4" fill="#64775c"/><rect x="-4" y="-5" width="9" height="10" rx="2" fill="#d4dfcc"/></g>';return s;}
